-- CC_0177_mo_legislature_incumbents.sql
-- St. Louis MO deep seed, wave 2 (occupancy half). Slot RESERVED from the allocator.
-- Applied back to back with CC_0176, which creates the 2 chambers and the 197 offices.
-- GENERATED by backend/data/seed-st-louis-mo-2026/occupancy-scripts/gen_cc0177.py from
-- mo-occupancy-2026-09-28.json. Edit the generator, not this file.
--
-- Seats 188 of the 197 members of the 103rd Missouri General Assembly -- 155 representatives and
-- 33 senators -- and flags the other 9 seats vacant. Creates 187 people and REUSES 1.
--
-- ---------------------------------------------------------------------------------------------
-- 🔴🔴 EVERY term_start HERE IS AN OCCUPANCY START, NOT A TERM START. Ruled 2026-09-28 (Cantrell).
-- essentials.office_terms models OCCUPANCY -- seat_officeholder closes the predecessor the day
-- before, and re-election does not end an occupancy -- so a Missouri representative re-elected in
-- 2024 did not begin a new occupancy on 2025-01-08.
--
--   123 terms  2023-01-04  the member is certified at THIS district number in the 102nd General
--                          Assembly's first-day Journal and has held it continuously since
--    65 terms  2025-01-08  the member is first certified at this district in the 103rd
--
-- ⚠ THIS DELIBERATELY DIFFERS FROM CC_0157 (Kansas) AND CC_0164 (South Dakota), which wrote the
-- CURRENT TERM START -- 119 of 125 Kansas House members carry 2025-01-13 regardless of how long
-- they had served. That is the documented fallback and it is cheaper. Missouri's Journals sell the
-- deeper answer for the cost of two PDFs per chamber, so the fallback was not needed here.
--
-- 🔴 THE FLOOR IS AT 2023-01-04 BECAUSE THAT IS WHERE THE GEOGRAPHY STOPS BEING TRUE. Production
-- holds only 2022-plan polygons. House District 78 before January 2023 covered different ground,
-- so reaching occupancy back to 2021 or 2019 would make essentials.office_holders_as_of() name the
-- right person for territory that district did not cover. The 100th (2019) and 101st (2021)
-- Journals were downloaded and read, and are deliberately NOT used.
--
-- 🟢 THE EVIDENCE IS KEYED BY DISTRICT NUMBER, SO NO NAME MATCHING IS REQUIRED ANYWHERE. Each
-- first-day Journal prints the Secretary of State's s 115.525 RSMo certification as a numbered
-- list -- "78th Rasheen Aldridge Jr." -- on the day the oath was administered. That is what makes
-- the homonym traps below harmless: nothing here is resolved by a name.
--   The House Journal itself disambiguates Brown 149 / Brown 16 / Brown 27 / Brown 87,
--   Smith 46 / Smith 155 / Smith 163, Taylor 48 / Taylor 84, Johnson 12 / Johnson 23 -- and lists
--   ⚠ Sharp 37 and Sharpe 4, two different people one letter apart.
--
-- ⚠ NEITHER ROSTER FIELD CAN BE TURNED INTO A DATE, AND BOTH WERE TESTED. The House publishes
-- 'Elected:' (an election year) and 'Years Served:' (years in the CHAMBER, not in the district).
-- Mark Matthiesen (HD-107) reads 'Elected 2016' with 6 years served, and John Simmons (HD-109)
-- reads 'Elected 2024' with 6 -- both are gaps in service that no arithmetic recovers. The
-- Journals date both exactly: Matthiesen is certified at HD-107 in the 102nd, so he carries
-- 2023-01-04; Simmons held HD-109 in 2019 and 2021, LOST IT TO KYLE MARQUART IN 2023, and returned
-- in 2025, so his current occupancy starts 2025-01-08.
--
-- 🔴 HD-2 IS A SURNAME CHANGE, NOT A CHANGE OF PERSON. The 102nd Journal certifies 'Mazzie Boyd'
-- and the 103rd certifies 'Mazzie Christensen'; the roster's independent 'Elected' field reads
-- 2022 for both. Matching on the name alone writes 2025-01-08 and understates her occupancy by two
-- years. Resolved from house.mo.gov/MemberDetails.aspx?district=002&year=2023, which names
-- Christensen at the 2023 seat.
--   🟢 That page got its own control, because a departed official's URL can serve their successor:
--   ?district=109&year=2023 returns Kyle Marquart and &year=2025 returns John Simmons, so the year
--   parameter is honoured and the read is real. HD-2 was the ONLY contradiction in 197 seats.
--
-- ---------------------------------------------------------------------------------------------
-- 🔴🔴 SIX NAMES ALREADY EXIST IN PRODUCTION. FIVE ARE DIFFERENT PEOPLE AND ONE IS THE SAME
-- PERSON. Getting either direction wrong is silent.
--
--   Mike Jones         (HD-12) -- production's Mike Jones holds PENNSYLVANIA State House 93
--   Michael Johnson    (HD-23) -- production's Michael Johnson holds SOUTH CAROLINA Senate 16
--   Chad Perkins       (HD-40) -- production's Chad Perkins holds MAINE State House 31
--   David Tyson Smith  (HD-46) -- production's David Smith holds FLORIDA State House 38
--   Brian Williams     (SD-14) -- production's Brian H Williams is an INDIANA Superior Court judge
--
-- Each of those five currently holds a seat in another state, and nobody holds two at once, so
-- none can be the Missourian; new people are created with the duplicate-name guard lifted for that
-- one statement.
--
-- 🔴🔴 A full_name SWEEP IS NOT THE GUARD'S TEST, AND MISSED TWO OF THE FIVE.
-- essentials.politician_name_duplicate_guard() keys on
--   lower(btrim(first_name)) AND lower(btrim(last_name)), over ACTIVE rows only.
-- 'David Tyson Smith' and 'David Smith' have different full names and the SAME (first, last), and
-- so do 'Brian Williams' and 'Brian H Williams'. The full_name sweep found 4 of 6; the guard threw
-- on the 5th during the dry run. occupancy-scripts/gen_guardcheck.py now applies the guard's own
-- predicate to all 188 -- run it before regenerating this file.
--
-- 🟢 THE REUSE SET WAS SWEPT THREE WAYS, and the third sweep found a real match, so it was not
-- blind: an exact-name join (4 hits, above); a last-name + first-initial sweep restricted to rows
-- carrying stances or a Missouri race (35 hits, every one an officeholder in another state, 0 with
-- a Missouri race); and a sweep of the 105 JOURNAL name forms, which returned Denny Hoskins --
-- SD-21's senator in the 102nd, now MISSOURI SECRETARY OF STATE and already seated in production
-- with 14 stances. He is a PREDECESSOR, never a holder here, so no action -- but he is the
-- positive control that proves the sweep can find something.
--
-- ---------------------------------------------------------------------------------------------
-- 🔴 NINE SEATS ARE VACANT: House 29, 95, 99, 110, 114, 149, 159, 160 and Senate 10. They get
-- offices.is_vacant and NO term row. Per CLAUDE.md a vacancy span whose start date is unknown must
-- NOT be written, and no resignation letter or writ of special election has been read for any of
-- them. essentials.vacate_office() is deliberately NOT used: it requires a first vacant day.
--   SD-10's vacancy has the Senate's own notice -- senate.mo.gov/senators/ carries
--   Senators/VacantSenator?district=10 and the text "Vacant District 10" -- not merely an absent
--   member card. The eight House vacancies carry the member grid's literal 'District Vacant', and
--   are confirmed a second way: those 8 detail pages are exactly the 8 publishing no 'Elected'
--   value.
--
-- 🔴 is_incumbent IS SET EXPLICITLY ON EVERY INSERT. It defaults to false since CA_0188, and a
-- seated person inserted without it is HIDDEN from address search.
--
-- 🔴 PARTY IS NOT WRITTEN. The House grid carries it (105 R, 50 D); party lives on
-- races.primary_party, never on a person.
--
-- 🟢 THE RESERVED external_id BAND IS -2790388 .. -2790202 (187 ids), MEASURED EMPTY on 2026-09-28
-- with margin either side, against a control on South Dakota's band that correctly returned 105.
--
-- ⚠ A GENERAL ELECTION FALLS FIVE WEEKS AFTER THIS WAS MEASURED (2026-11-03) and the 104th General
-- Assembly convenes in January 2027. Everyone seated here is correct TODAY. SD-4 is already known
-- to change: Karla May is term-limited and Gina Mitten won the August primary. Current occupancy
-- is seeded; the winners of an election that has not happened are not.
--
-- Idempotent: every INSERT is NOT EXISTS-guarded and both UPDATEs are guarded. Ends with a
-- post-verify gate.

BEGIN;

-- --- 1. The 182 new people with no namesake in production --------------------

CREATE TEMP TABLE mo_new_people(external_id bigint, full_name text, first_name text, last_name text)
  ON COMMIT DROP;


SELECT n.external_id, n.full_name, n.first_name, n.last_name, 'Missouri General Assembly. Membership from each chamber''s own roster, read 2026-09-28 - house.mo.gov/MemberGridCluster.aspx?filter=compact&year=2026&code=R with all 163 member detail pages fetched (0 errors), and senate.mo.gov/senators/ (33 member cards; District 10 carries the Senate''s own VacantSenator notice). OCCUPANCY IS DATED FROM THE SECRETARY OF STATE''S s 115.525 RSMo CERTIFICATION, KEYED BY DISTRICT NUMBER, printed in each chamber''s first-day Journal on the day the oath was administered: Journal of the House and Journal of the Senate, 102nd General Assembly, FIRST DAY, WEDNESDAY, JANUARY 4, 2023 (documents.house.mo.gov/billtracking/bills231/jrnpdf/jrn001.pdf; senate.mo.gov/23info/Journals/RDay0101041-87.pdf), and 103rd General Assembly, FIRST DAY, WEDNESDAY, JANUARY 8, 2025 (documents.house.mo.gov/billtracking/bills251/jrnpdf/jrn001.pdf; senate.mo.gov/25info/Journals/RDay0101081-80.pdf). THIS IS AN OCCUPANCY START, NOT A TERM START: a member certified at this district in the 102nd carries 2023-01-04, the first day the 2022 district plan had officeholders, and the floor is there because production holds only 2022-plan polygons. (MO-2) (CC_0177, MO-2)', true, true
FROM mo_new_people n
WHERE NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.external_id = n.external_id);

-- --- 2. The five namesakes - guard lifted for this statement only ------------
-- Each of these three names belongs to a DIFFERENT person who currently holds a seat in another
-- state, so no row is reused. Checked, not assumed.

SET LOCAL essentials.allow_duplicate_name = 'on';

CREATE TEMP TABLE mo_namesake_people(external_id bigint, full_name text, first_name text, last_name text)
  ON COMMIT DROP;


SELECT n.external_id, n.full_name, n.first_name, n.last_name, 'Missouri General Assembly. Membership from each chamber''s own roster, read 2026-09-28 - house.mo.gov/MemberGridCluster.aspx?filter=compact&year=2026&code=R with all 163 member detail pages fetched (0 errors), and senate.mo.gov/senators/ (33 member cards; District 10 carries the Senate''s own VacantSenator notice). OCCUPANCY IS DATED FROM THE SECRETARY OF STATE''S s 115.525 RSMo CERTIFICATION, KEYED BY DISTRICT NUMBER, printed in each chamber''s first-day Journal on the day the oath was administered: Journal of the House and Journal of the Senate, 102nd General Assembly, FIRST DAY, WEDNESDAY, JANUARY 4, 2023 (documents.house.mo.gov/billtracking/bills231/jrnpdf/jrn001.pdf; senate.mo.gov/23info/Journals/RDay0101041-87.pdf), and 103rd General Assembly, FIRST DAY, WEDNESDAY, JANUARY 8, 2025 (documents.house.mo.gov/billtracking/bills251/jrnpdf/jrn001.pdf; senate.mo.gov/25info/Journals/RDay0101081-80.pdf). THIS IS AN OCCUPANCY START, NOT A TERM START: a member certified at this district in the 102nd carries 2023-01-04, the first day the 2022 district plan had officeholders, and the floor is there because production holds only 2022-plan polygons. (MO-2) (CC_0177, MO-2)', true, true
FROM mo_namesake_people n
WHERE NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.external_id = n.external_id);

SET LOCAL essentials.allow_duplicate_name = 'off';

-- --- 3. The one reused person - SD-31 Rick Brattin --------------------------
-- is_incumbent was false, which was correct while the row was only a congressional candidate
-- record. He is a sitting state senator, and the incumbents-only reads filter on this flag.

UPDATE essentials.politicians
   SET is_incumbent = true, is_active = true
 WHERE id = 'e9ec322c-e997-486d-8202-48423671c800'
   AND external_id = -290502
   AND is_incumbent IS DISTINCT FROM true;

-- --- 4. The 188 terms -------------------------------------------------------
-- Keyed on (geo_id, district_type). NEVER geo_id alone: 82 Missouri counties share a geo_id with
-- a House district, 17 with a Senate district, and all 34 Senate districts share one with a House
-- district. '29099' is Jefferson County AND House District 99.

CREATE TEMP TABLE mo_terms(
  geo_id text, district_type text, external_id bigint, term_start date, start_precision text, how_started text
) ON COMMIT DROP;


SELECT o.id, p.id, t.term_start, NULL, t.start_precision, t.how_started, 'Missouri General Assembly. Membership from each chamber''s own roster, read 2026-09-28 - house.mo.gov/MemberGridCluster.aspx?filter=compact&year=2026&code=R with all 163 member detail pages fetched (0 errors), and senate.mo.gov/senators/ (33 member cards; District 10 carries the Senate''s own VacantSenator notice). OCCUPANCY IS DATED FROM THE SECRETARY OF STATE''S s 115.525 RSMo CERTIFICATION, KEYED BY DISTRICT NUMBER, printed in each chamber''s first-day Journal on the day the oath was administered: Journal of the House and Journal of the Senate, 102nd General Assembly, FIRST DAY, WEDNESDAY, JANUARY 4, 2023 (documents.house.mo.gov/billtracking/bills231/jrnpdf/jrn001.pdf; senate.mo.gov/23info/Journals/RDay0101041-87.pdf), and 103rd General Assembly, FIRST DAY, WEDNESDAY, JANUARY 8, 2025 (documents.house.mo.gov/billtracking/bills251/jrnpdf/jrn001.pdf; senate.mo.gov/25info/Journals/RDay0101081-80.pdf). THIS IS AN OCCUPANCY START, NOT A TERM START: a member certified at this district in the 102nd carries 2023-01-04, the first day the 2022 district plan had officeholders, and the floor is there because production holds only 2022-plan polygons. (MO-2) (CC_0177, MO-2)'
FROM mo_terms t
JOIN essentials.districts d
  ON d.geo_id = t.geo_id AND d.district_type::text = t.district_type AND lower(d.state) = 'mo'
JOIN essentials.offices o ON o.district_id = d.id
JOIN essentials.politicians p ON p.external_id = t.external_id
WHERE NOT EXISTS (SELECT 1 FROM essentials.office_terms ot WHERE ot.office_id = o.id);

-- --- 5. The 9 vacancies - a flag, and deliberately NO term row --------------

CREATE TEMP TABLE mo_vacant(geo_id text, district_type text) ON COMMIT DROP;


UPDATE essentials.offices o
   SET is_vacant = true
  FROM mo_vacant v, essentials.districts d
 WHERE d.geo_id = v.geo_id
   AND d.district_type::text = v.district_type
   AND lower(d.state) = 'mo'
   AND o.district_id = d.id
   AND o.is_vacant IS DISTINCT FROM true;

-- --- Post-verify gate -------------------------------------------------------

DO $$
DECLARE
  v_people    int;
  v_brattin   int;
  v_terms     int;
  v_seated_h  int;
  v_seated_s  int;
  v_vacant    int;
  v_vac_terms int;
  v_notday    int;
  v_2023      int;
  v_2025      int;
  v_otherdate int;
  v_noninc    int;
  v_outside   int;
  v_dupe      int;
  v_missing   int;
BEGIN
  SELECT count(*) INTO v_people FROM essentials.politicians
   WHERE external_id BETWEEN -2790388 AND -2790202;
  IF v_people <> 187 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: expected 187 people in the reserved band, got %', v_people;
  END IF;

  -- The reuse, asserted as a reuse: exactly one Rick Brattin, and he is an incumbent now.
  SELECT count(*) INTO v_brattin FROM essentials.politicians
   WHERE lower(full_name) = 'rick brattin';
  IF v_brattin <> 1 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: expected exactly 1 Rick Brattin row (his 10 stances must not be split), found %', v_brattin;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM essentials.politicians
                  WHERE id = 'e9ec322c-e997-486d-8202-48423671c800' AND is_incumbent IS true) THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: the reused Rick Brattin row is not flagged is_incumbent — he would be hidden from address search';
  END IF;

  -- 🔴 Count och.politician_id, NOT *: office_current_holder LEFT JOINs from offices, so a vacancy
  -- is a NULL politician_id and count(*) would pass vacuously on an empty result.
  SELECT count(och.politician_id) INTO v_seated_h
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE lower(d.state) = 'mo' AND d.district_type::text = 'STATE_LOWER';
  SELECT count(och.politician_id) INTO v_seated_s
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE lower(d.state) = 'mo' AND d.district_type::text = 'STATE_UPPER';
  IF v_seated_h <> 155 OR v_seated_s <> 33 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: expected 155 House and 33 Senate seated, found % and %', v_seated_h, v_seated_s;
  END IF;

  SELECT count(*) INTO v_terms
    FROM essentials.office_terms ot
    JOIN essentials.offices o ON o.id = ot.office_id
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER');
  IF v_terms <> 188 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: expected 188 MO legislative terms, found %', v_terms;
  END IF;

  SELECT count(*) INTO v_vacant
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER')
     AND o.is_vacant IS true;
  IF v_vacant <> 9 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: expected exactly 9 vacant MO legislative seats (House 29/95/99/110/114/149/159/160, Senate 10), found %', v_vacant;
  END IF;

  -- 🔴 A vacancy must carry NO term row. This is the assertion that would catch a vacancy
  -- accidentally seated, which the 188 total alone cannot see.
  SELECT count(*) INTO v_vac_terms
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.office_terms ot ON ot.office_id = o.id
   WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER')
     AND o.is_vacant IS true;
  IF v_vac_terms <> 0 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: % vacant MO legislative seat(s) carry a term row — a vacancy span with an unknown start must not be written', v_vac_terms;
  END IF;

  -- Every term dated to the day, and to one of exactly two days.
  SELECT count(*) INTO v_notday
    FROM essentials.office_terms ot
    JOIN essentials.offices o ON o.id = ot.office_id
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER')
     AND (ot.start_precision <> 'day' OR ot.term_start IS NULL);
  IF v_notday <> 0 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: % MO legislative term(s) are not day-precision with a real date', v_notday;
  END IF;

  SELECT
    count(*) FILTER (WHERE ot.term_start = DATE '2023-01-04'),
    count(*) FILTER (WHERE ot.term_start = DATE '2025-01-08'),
    count(*) FILTER (WHERE ot.term_start NOT IN (DATE '2023-01-04', DATE '2025-01-08'))
    INTO v_2023, v_2025, v_otherdate
    FROM essentials.office_terms ot
    JOIN essentials.offices o ON o.id = ot.office_id
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER');
  IF v_otherdate <> 0 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: % MO legislative term(s) carry a date that is neither first day (2023-01-04 / 2025-01-08)', v_otherdate;
  END IF;
  IF v_2023 <> 123 OR v_2025 <> 65 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: expected 123 terms at 2023-01-04 and 65 at 2025-01-08, found % and %', v_2023, v_2025;
  END IF;

  -- 🔴 Every seated person must be flagged is_incumbent, or they vanish from address search.
  SELECT count(*) INTO v_noninc
    FROM essentials.office_terms ot
    JOIN essentials.offices o ON o.id = ot.office_id
    JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.politicians p ON p.id = ot.politician_id
   WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER')
     AND (p.is_incumbent IS DISTINCT FROM true OR p.is_active IS DISTINCT FROM true);
  IF v_noninc <> 0 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: % seated MO legislator(s) are not is_incumbent/is_active — they would be hidden from address search', v_noninc;
  END IF;

  -- 🔴🔴 The Minnesota guard, restated on the occupancy side. Nobody this file seats may land on a
  -- district outside Missouri — St. Louis County exists in BOTH states with the same label and the
  -- same seat count.
  SELECT count(*) INTO v_outside
    FROM essentials.office_terms ot
    JOIN essentials.offices o ON o.id = ot.office_id
    JOIN essentials.chambers c ON c.id = o.chamber_id
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE c.government_id = '066b88fd-1458-462e-a3b5-1331f1810fdf'
     AND lower(coalesce(d.state, '')) <> 'mo';
  IF v_outside <> 0 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: % Missouri-chamber term(s) sit on a district outside Missouri — the St. Louis County homonym (MN 27137 vs MO 29189)', v_outside;
  END IF;

  -- No person holds two Missouri legislative seats. office_terms' exclusion constraint forbids two
  -- people on one office; it CANNOT see one person on two, which is the fan-out CLAUDE.md warns of.
  SELECT count(*) INTO v_dupe FROM (
    SELECT ot.politician_id
      FROM essentials.office_terms ot
      JOIN essentials.offices o ON o.id = ot.office_id
      JOIN essentials.districts d ON d.id = o.district_id
     WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER')
     GROUP BY 1 HAVING count(*) > 1) x;
  IF v_dupe <> 0 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: % person(s) hold more than one MO legislative seat', v_dupe;
  END IF;

  -- 🔴 The failure mode CI cannot catch: a seat with no term row is invisible and nothing errors.
  -- 197 offices, 188 terms, 9 flagged vacant — so every unflagged seat must carry a term.
  SELECT count(*) INTO v_missing
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
   WHERE lower(d.state) = 'mo' AND d.district_type::text IN ('STATE_UPPER', 'STATE_LOWER')
     AND o.is_vacant IS NOT true
     AND NOT EXISTS (SELECT 1 FROM essentials.office_terms ot WHERE ot.office_id = o.id);
  IF v_missing <> 0 THEN
    RAISE EXCEPTION 'MO-2 occupancy gate: % unflagged MO legislative seat(s) carry no term row — invisible, and nothing would error', v_missing;
  END IF;

  RAISE NOTICE 'MO-2 occupancy gate PASSED: 187 new people + 1 reused, 188 terms (123 at 2023-01-04, 65 at 2025-01-08, all day precision), 155 House + 33 Senate seated, 9 vacant carrying no term, 0 outside Missouri, 0 double-seated, 0 unflagged seat without a term.';
END $$;

COMMIT;
